import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Search, SlidersHorizontal, X } from 'lucide-react';
import AppLayout from '../components/AppLayout';
import { FoodCardRow, C } from '../components/UI';
import { FOOD_ITEMS, RECENT_SEARCHES, POPULAR_FILTERS, POPULAR_CATEGORIES } from '../data/mockData';

export default function SearchScreen() {
  const navigate = useNavigate();
  const [query, setQuery] = useState('');
  const [activeFilter, setActiveFilter] = useState('');

  const results = query.length > 1
    ? FOOD_ITEMS.filter(f =>
        f.name.toLowerCase().includes(query.toLowerCase()) ||
        f.tags.some(t => t.toLowerCase().includes(query.toLowerCase())) ||
        f.category.toLowerCase().includes(query.toLowerCase())
      )
    : [];

  const pillBtn = (label, active, onClick) => (
    <button
      key={label}
      onClick={onClick}
      style={{
        padding: '7px 14px', borderRadius: 20, flexShrink: 0,
        background: active ? C.orange : '#1e1e1e',
        color: active ? '#fff' : '#888',
        border: `1px solid ${active ? C.orange : '#2a2a2a'}`,
        fontSize: 12, fontWeight: 600, cursor: 'pointer', transition: 'all 0.2s',
      }}
    >
      {label}
    </button>
  );

  return (
    <AppLayout>
      {/* Search Header */}
      <div style={{ padding: '20px 16px 12px', display: 'flex', alignItems: 'center', gap: 10 }}>
        <button onClick={() => navigate(-1)} style={{ background: 'none', border: 'none', color: '#fff', fontSize: 20, cursor: 'pointer' }}>←</button>
        <div style={{
          flex: 1, display: 'flex', alignItems: 'center', gap: 8,
          background: '#1e1e1e', border: `1px solid ${C.border}`,
          borderRadius: 12, padding: '11px 14px',
        }}>
          <Search size={16} color="#666" />
          <input
            autoFocus
            placeholder="Search for food, cuisines..."
            value={query}
            onChange={e => setQuery(e.target.value)}
            style={{ flex: 1, background: 'none', border: 'none', color: '#fff', fontSize: 14, outline: 'none' }}
          />
          {query && (
            <button onClick={() => setQuery('')} style={{ background: 'none', border: 'none', color: '#666', cursor: 'pointer' }}>
              <X size={14} />
            </button>
          )}
        </div>
        <button style={{ background: 'none', border: 'none', color: '#ccc', cursor: 'pointer' }}>
          <SlidersHorizontal size={18} />
        </button>
      </div>

      {query.length > 1 ? (
        /* Results */
        <div style={{ padding: '0 16px' }}>
          <p style={{ fontSize: 13, color: '#666', marginBottom: 14 }}>{results.length} results for "{query}"</p>
          {results.length === 0
            ? <p style={{ color: '#555', textAlign: 'center', marginTop: 40 }}>No results found 😕</p>
            : results.map(food => <FoodCardRow key={food.id} food={food} />)
          }
        </div>
      ) : (
        /* Discovery */
        <div style={{ padding: '0 16px' }}>
          {/* Recent searches */}
          <div style={{ marginBottom: 24 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 12 }}>
              <span style={{ fontSize: 14, fontWeight: 700, color: '#fff' }}>Recent Searches</span>
              <button style={{ background: 'none', border: 'none', color: C.orange, fontSize: 12, fontWeight: 600, cursor: 'pointer' }}>Clear all</button>
            </div>
            <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
              {RECENT_SEARCHES.map(s => (
                <button
                  key={s} onClick={() => setQuery(s)}
                  style={{
                    padding: '7px 14px', borderRadius: 20,
                    background: '#1e1e1e', border: `1px solid ${C.border}`,
                    color: '#ccc', fontSize: 13, cursor: 'pointer',
                  }}
                >
                  {s}
                </button>
              ))}
            </div>
          </div>

          {/* Popular Categories */}
          <div style={{ marginBottom: 24 }}>
            <p style={{ fontSize: 14, fontWeight: 700, color: '#fff', marginBottom: 12 }}>Popular Categories</p>
            <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
              {POPULAR_CATEGORIES.map(c => pillBtn(c, false, () => setQuery(c)))}
            </div>
          </div>

          {/* Popular Filters */}
          <div style={{ marginBottom: 16 }}>
            <p style={{ fontSize: 14, fontWeight: 700, color: '#fff', marginBottom: 12 }}>Popular Filters</p>
            <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
              {POPULAR_FILTERS.map(f => pillBtn(f, activeFilter === f, () => setActiveFilter(v => v === f ? '' : f)))}
            </div>
          </div>
        </div>
      )}
    </AppLayout>
  );
}
